using NexOS.Forms;

namespace NexOS.Forms
{
    // =================================================================
    //  Notepad (text viewer / scratch editor)
    // =================================================================
    public class NotepadApp : App
    {
        TBox t;        // 编辑器模型（光标 + 选区 + 撤销）
        string name;   // 当前加载的文件
        bool picking;   // 正在显示打开列表
        bool saved;    // 上次操作是成功的 Ctrl+S（标题提示）
        bool binary;   // 文件不是可解码文本 -> 显示十六进制视图
        string hex;    // 原始字节的十六进制（仅 binary 时有意义）
        int fs;     // 文档所在卷（0=MKFS 根，3=桌面）

        // === 新增：分块加载状态 ===
        int loadTotal;     // 文件总字节数（0 = 无加载任务）
        int loadDone;      // 已解码进 t.text 的字节数
        string loadHex;       // 源文件的完整 hex（分块解码用）
        bool loadActive;    // 是否正在分块加载
        const int LOAD_CHUNK = 4096;   // 每帧解码字节数（调这个控制流畅度）

        // === 新增：鼠标选区状态 ===
        int selAnchorPos = -1;  // 选区锚点（字节偏移），-1 = 无
        bool mouseSelecting = false; // 正在拖选
        int lastCaretByte = -1;  // 拖动时用于避免重复重算

        public NotepadApp()
        {
            t = new TBox();
            string pending = Shell.TakeNotepadFile();
            if (pending != null && pending != "")
                LoadFile(Shell.TakeNotepadFs(), pending);
            else
            {
                t.text = "Untitled - type below, or click Open to read a file.";
                name = "Untitled";
                fs = 0;
                binary = false; hex = "";
            }
            picking = false;
            saved = false;
        }

        // ---- 唯一的文件打开路径 ------------------------------------
        // 应用内 Open 选择器过去直接调用 Host.ReadText() 并完全跳过原始字节探测。
        // .mex 是二进制 "MEX1" 镜像：ReadText 会把其中的 NUL / 控制字节清洗成空格和点，
        // 于是编辑器收到空白页，文件看起来无法打开。走与 shell 交接相同的加载器，
        // 二进制文件会进入现有十六进制视图，文本文件（txt / md / json / html ...）保持原样。
        void LoadFile(int pfs, string fname)
        {
            name = fname;
            fs = pfs;

            // === 修改：加载改为“先探测、再分块解码” ===
            // 先只取 hex 做二进制探测（hex 是整文件，但只读一次；
            // 真正耗时的“hex -> UTF-8 文本”解码拆到 OnPaint 每帧做）。
            string hx = Host.ReadHex(pfs, fname);
            if (hx == "")
            {
                int alt = (pfs == 1) ? 0 : 1;
                string altHex = Host.ReadHex(alt, fname);
                if (altHex != "") { hx = altHex; fs = alt; }
            }

            t.cursor = 0;
            t.selA = t.selB = 0;
            saved = false;
            selAnchorPos = -1;
            mouseSelecting = false;

            if (IsBinaryHex(hx))
            {
                binary = true; hex = hx; t.text = "";
                loadActive = false; loadTotal = 0; loadDone = 0; loadHex = null;
                Host.Log(U.Cat("[EDITOR] 1", fname));
            }
            else
            {
                binary = false; hex = "";
                // === 新增：文本文件走分块加载 ===
                // 小文件（< 2 个 chunk）一帧内解完，大文件每帧只解 LOAD_CHUNK 字节，
                // 期间可以滚动/点击，不会冻住窗口。
                t.text = "";
                loadHex = hx;                 // hex 是 2 倍字节的 ASCII 串
                loadTotal = hx.Length / 2;    // 实际文件字节数
                loadDone = 0;
                if (loadTotal <= LOAD_CHUNK)
                {
                    // 小文件：立即解码，避免多一帧的“空窗口”
                    t.text = Host.ReadText(fs, fname);
                    if (t.text == "") t.text = "Untitled - type below, or click Open to read a file.";
                    loadActive = false; loadHex = null; loadDone = loadTotal;
                }
                else
                {
                    // 大文件：标记为正在加载，OnPaint 每帧推进
                    loadActive = true;
                }
                Host.Log(U.Cat("[EDITOR] 0 ", U.I(loadTotal), " bytes ", fname));
            }
        }

        // === 新增：从 hex 串的某段偏移解码出一段 UTF-8 文本 ===
        // 不能直接用 Host.ReadText，因为那会整文件读；这里用已有的 U.Cat /
        // Host.CharStr 把 hex 的对应区间逐字节还原成字符串。
        // 注意：切分点可能落在多字节字符中间，所以解码到“最后一个完整字符”为止，
        // 剩余字节留给下一次。
        string DecodeHexRange(string hx, int byteStart, int byteCount, out int consumed)
        {
            consumed = 0;
            string outS = "";
            int total = hx.Length / 2;
            int i = byteStart;
            int end = byteStart + byteCount;
            if (end > total) end = total;
            while (i < end)
            {
                int v = HxByte(hx, i * 2);
                if (v < 0) break;
                // 处理 UTF-8 多字节序列
                int need = 0;
                if (v < 0x80) need = 1;
                else if ((v & 0xE0) == 0xC0) need = 2;
                else if ((v & 0xF0) == 0xE0) need = 3;
                else if ((v & 0xF8) == 0xF0) need = 4;
                else need = 1;   // 非法起始字节，按单字节吞掉，避免死循环
                if (i + need > total || i + need > end)
                    break;       // 跨块或越界：留给下一块
                                 // 重组这段字节为一个字符（MiniCLR 无 StringBuilder，用 U.Cat）
                for (int k = 0; k < need; k++)
                {
                    int b = HxByte(hx, (i + k) * 2);
                    outS = U.Cat(outS, Host.CharStr(b));
                }
                i += need;
            }
            consumed = i - byteStart;
            return outS;
        }

        // ---- 二进制检测 / 十六进制格式化（原样） --------------------------
        static int HxNib(int c)
        {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return c - 'a' + 10;
            if (c >= 'A' && c <= 'F') return c - 'A' + 10;
            return -1;
        }
        static int HxByte(string h, int i)
        {
            if (i + 1 >= h.Length) return -1;
            int a = HxNib((int)h[i]), b = HxNib((int)h[i + 1]);
            if (a < 0 || b < 0) return -1;
            return (a << 4) | b;
        }
        static bool IsBinaryHex(string h)
        {
            if (h == null) return false;
            int n = h.Length / 2;
            for (int i = 0; i < n; i++)
            {
                int v = HxByte(h, i * 2);
                if (v < 0) return true;
                if (v == 0) return true;
                if (v < 0x20 && v != 9 && v != 10 && v != 13) return true;
                if (v == 0x7F) return true;
            }
            return false;
        }

        // ---- 保存目标（原样） --------------------------------------------
        static readonly string[] VolNames = { "MKFS root", "Desktop folder" };
        int saveVol;
        bool pickingSave;
        string saveNameBuf;
        int saveDirWarn;

        int SaveFs() { return saveVol == 1 ? 3 : 0; }

        void Save()
        {
            int wr = Host.WriteText(fs, name, t.text);
            Host.Log(U.Cat(wr >= 0 ? "[EDITOR] saved " : "[EDITOR] SAVE FAILED ", name));
            saveDirWarn = wr < 0 ? 1 : 0;
            saved = true;
        }

        void SaveAs()
        {
            string nm = saveNameBuf;
            if (nm == null || nm == "") nm = "Untitled.txt";
            int dot = -1;
            for (int i = nm.Length - 1; i >= 0; i--) { if (nm[i] == '.') { dot = i; break; } }
            if (dot <= 0) nm = U.Cat(nm, "." + DetectExt());
            name = nm;
            fs = SaveFs();
            int wr = Host.WriteText(fs, name, t.text);
            Host.Log(U.Cat(wr >= 0 ? "[EDITOR] saved-as " : "[EDITOR] SAVE-AS FAILED ", name));
            saveDirWarn = wr < 0 ? 1 : 0;
            saved = true;
            pickingSave = false;
        }

        // ---- 内容嗅探（原样） --------------------------------------------
        static bool StartsWith(string s, string p)
        {
            if (s == null || p == null) return false;
            if (p.Length > s.Length) return false;
            for (int i = 0; i < p.Length; i++) if (s[i] != p[i]) return false;
            return true;
        }

        static string DetectExtStatic(string body)
        {
            if (body == null || body.Length == 0) return "txt";
            if (body.Length >= 12 && StartsWith(body, "{\\rtf")) return "rtf";
            if (StartsWith(body, "<?xml")) return "xml";
            if (StartsWith(body, "<!DOCTYPE html") || StartsWith(body, "<!doctype html")
                || StartsWith(body, "<html")) return "html";
            if (StartsWith(body, "{")) return "json";
            if (StartsWith(body, ";;") || StartsWith(body, "; ")) return "ini";
            if (StartsWith(body, "---")) return "md";
            for (int i = 0; i < body.Length && i < 40; i++)
                if (body[i] == '#') return "md";
            return "txt";
        }
        string DetectExt() { return DetectExtStatic(t.text); }

        string DetectLabel()
        {
            string e = DetectExt();
            if (e == "rtf") return "Rich Text (RTF source)";
            if (e == "xml") return "XML markup";
            if (e == "html") return "HTML document";
            if (e == "json") return "JSON data";
            if (e == "ini") return "INI / config";
            if (e == "md") return "Markdown";
            return "Plain text";
        }

        public override string GetTitle() { return U.Cat("Notepad - ", name); }

        // 宽度感知字形模型（与内核 mh_measure / Gfx.Measure 以及绘制正文用的
        // draw_text_utf8 前进量一致）：8px ASCII，16px CJK。MiniCLR 字符串是
        // UTF-8 字节数组，因此在 i 处解码序列：一个 3 字节 CJK 字符是一个
        // 16px 字形，不是三个。
        static int NpAdv(string s, int i) { return ((int)s[i] < 0x80) ? 8 : 16; }
        static int NpBytes(string s, int i)
        {
            int b = (int)s[i];
            if (b < 0x80) return 1;
            if ((b & 0xE0) == 0xC0) return 2;
            if ((b & 0xF0) == 0xE0) return 3;
            if ((b & 0xF8) == 0xF0) return 4;
            return 1;
        }
        static int NpWidth(string s, int start, int n)
        {
            if (s == null) return 0;
            if (start < 0) start = 0;
            if (n > s.Length - start) n = s.Length - start;
            int w = 0, i = start, end = start + n;
            while (i < end) { w += NpAdv(s, i); i += NpBytes(s, i); }
            return w;
        }

        // === 新增：把屏幕坐标 (mx,my) 反算成文本字节偏移 ===
        // 行高 20，左边距 pad+8，首行 y=54。列方向按字符宽度累加。
        int HitTestByte(int mx, int my, int pad)
        {
            if (t.text == null) return 0;
            int lineH = 20;
            int top = 54;
            int left = pad + 8;
            int line = (my - top) / lineH;
            if (line < 0) return 0;

            // 走到目标行的行首
            int pos = 0, curLine = 0;
            int n = t.text.Length;
            while (pos < n && curLine < line)
            {
                if (t.text[pos] == '\n') curLine++;
                pos++;
            }
            if (curLine < line) return n;   // 点击在末尾之后

            // 在行内按字符宽度前进
            int x = left;
            while (pos < n && t.text[pos] != '\n')
            {
                int adv = NpAdv(t.text, pos);
                if (mx < x + adv / 2) return pos;   // 落在字符左半 -> 该字符前
                x += adv;
                pos += NpBytes(t.text, pos);
            }
            return pos;
        }

        // === 新增：根据当前光标与锚点，更新 TBox 的选区 ===
        void UpdateSelectionFromMouse()
        {
            if (selAnchorPos < 0) { t.selA = t.selB = t.cursor; return; }
            int a = selAnchorPos, b = t.cursor;
            if (a > b) { int tmp = a; a = b; b = tmp; }
            t.selA = a;
            t.selB = b;
        }

        public override void OnPaint()
        {
            // === 新增：每帧推进分块加载 ===
            // 这是“异步”的核心：OnPaint 每帧被调用，这里解码一小块，
            // 大文件也不会一帧卡死。加载完成后 loadActive=false。
            if (loadActive && loadHex != null)
            {
                int consumed;
                string piece = DecodeHexRange(loadHex, loadDone, LOAD_CHUNK, out consumed);
                if (consumed > 0)
                {
                    t.text = U.Cat(t.text, piece);
                    loadDone += consumed;
                }
                // 若这一帧没消费到任何字节（比如只剩半字符），强制结束避免死循环
                if (consumed == 0 || loadDone >= loadTotal)
                {
                    loadActive = false;
                    if (loadDone < loadTotal)
                    {
                        // 末尾残余字节：补齐
                        int rest;
                        string tail = DecodeHexRange(loadHex, loadDone, loadTotal - loadDone, out rest);
                        t.text = U.Cat(t.text, tail);
                        loadDone += rest;
                    }
                    loadHex = null;
                    if (t.text == "") t.text = "Untitled - type below, or click Open to read a file.";
                }
                // 请求下一帧继续（宿主据此保持重绘循环）
                Host.Repaint();
            }

            W.Clear();
            int w = Gfx.Width(), h = Gfx.Height();
            int pad = 10;

            // 工具栏。
            Gfx.FillRect(0, 0, w, 40, 0xFAFAFA);
            Gfx.DrawLine(0, 40, w, 40, C.Border);
            W.Button(pad, 6, 70, 28, "Open");
            W.Button(pad + 80, 6, 70, 28, "New");
            W.Button(pad + 160, 6, 84, 28, "Save As");
            Gfx.Text(pad + 254, 12, name, C.TextSub);
            if (saved) { int sw = Gfx.Measure(name); Gfx.Text(pad + 262 + sw, 12, "(saved)", 0x107C10); }
            Gfx.Text(pad + 254, 30, DetectLabel(), C.TextFaint);
            if (saveDirWarn != 0)
                Gfx.Text(pad + 400, 12, "save failed - choose another folder", C.Danger);

            // === 新增：加载进度提示 ===
            if (loadActive)
            {
                int pct = loadTotal > 0 ? (loadDone * 100) / loadTotal : 0;
                Gfx.Text(pad + 254, 12, U.Cat("Loading ", U.I(pct), "%"), C.Accent);
            }

            if (pickingSave) { DrawSaveAs(w, h); return; }
            if (picking) { DrawPicker(w, h); return; }
            if (binary) { DrawBinary(pad, w, h); return; }

            // 文本正文。
            Gfx.FillRect(pad, 48, w - 2 * pad, h - 48 - pad, C.White);

            // === 修改：选区高亮（支持任意范围，不只是全选） ===
            // 原代码只处理 selA==0 && selB==len 的全选情况；这里按行遍历，
            // 把 [selA, selB) 的每一段都画上高亮。
            if (t.selB > t.selA && !loadActive)
            {
                DrawSelection(pad, w, t.selA, t.selB);
            }

            DrawLines(pad + 8, 54, t.text, C.Text, h - pad, false);

            // 光标（在最上层）—— 宽度感知，能跟随中文（16px）文本
            int cl = 0, lineStart = 0;
            for (int i = 0; i < t.cursor && i < t.text.Length; i++) { if (t.text[i] == '\n') { cl++; lineStart = i + 1; } }
            int colInLine = t.cursor - lineStart;
            if ((Host.Ticks() / 30) % 2 == 0)
            {
                int cxp = pad + 8 + NpWidth(t.text, lineStart, colInLine);
                int cyp = 54 + cl * 20;
                if (cyp < h - pad) Gfx.FillRect(cxp, cyp, 2, 18, 0x1A1A1A);
            }
            // 发布光标原点，使原生拼音候选 / 预编辑弹窗位于此行正上方并对齐。
            int anchorY = 54 + cl * 20;
            if (anchorY > h - 30) anchorY = h - 30;
#if !WINHOST
            Host.SetImeAnchor(pad + 8 + NpWidth(t.text, lineStart, colInLine), anchorY);
#endif
        }

        // === 新增：绘制任意范围选区的高亮 ===
        // 逐行处理：找出 [a,b) 覆盖到的每一行，算出该行内的起止列宽，
        // 画一个矩形。与 DrawLines 的行高 / 左边距保持一致。
        void DrawSelection(int pad, int w, int a, int b)
        {
            if (t.text == null || b <= a) return;
            int n = t.text.Length;
            if (a < 0) a = 0;
            if (b > n) b = n;
            int lineH = 20, top = 54, left = pad + 8;
            int pos = 0, line = 0, lineStart = 0;
            while (pos <= n)
            {
                bool eol = (pos == n || t.text[pos] == '\n');
                if (eol)
                {
                    int lineEnd = pos;
                    // 本行与 [a,b) 的交集
                    int s = (a > lineStart) ? a : lineStart;
                    int e = (b < lineEnd) ? b : lineEnd;
                    if (s < e)
                    {
                        int x1 = left + NpWidth(t.text, lineStart, s - lineStart);
                        int x2 = left + NpWidth(t.text, lineStart, e - lineStart);
                        int y = top + line * lineH;
                        if (x2 > x1) Gfx.FillRect(x1, y, x2 - x1, lineH - 2, 0xCDE6FF);
                    }
                    if (pos == n) break;
                    line++; lineStart = pos + 1;
                }
                pos++;
            }
        }

        // ---- Save As 对话框（原样） -------------------------------------
        void DrawSaveAs(int w, int h)
        {
            int pad = 10;
            Gfx.FillRect(0, 44, w, h - 44, 0xF7F7F7);
            Gfx.Text(pad + 8, 56, "Save as - choose a location and a file name", C.Text);
            int y = 84;

            Gfx.Text(pad + 8, y, "Volume:", C.TextSub);
            y += 22;
            for (int i = 0; i < 2; i++)
            {
                int ry = y + i * W.RowH;
                bool hot = W.Hot(pad, ry, w - 2 * pad, W.RowH - 2);
                if (saveVol == i) Gfx.FillRound(pad, ry, w - 2 * pad, W.RowH - 2, 6, C.Sel);
                else if (hot) Gfx.FillRound(pad, ry, w - 2 * pad, W.RowH - 2, 6, C.Hover);
                Gfx.Text(pad + 12, ry + 7, saveVol == i ? "(o)" : "( )", C.Text);
                Gfx.Text(pad + 44, ry + 7, VolNames[i], C.Text);
            }
            y += 2 * W.RowH + 10;

            int vfs = SaveFs();
            Gfx.Text(pad + 8, y, U.Cat("Folder: ", Host.CwdPath(vfs)), C.TextSub);
            y += 22;
            Gfx.Text(pad + 8, y, "File name:", C.TextSub);
            y += 22;
            Gfx.FillRect(pad + 8, y, w - 2 * pad - 16, 30, C.White);
            Gfx.DrawRect(pad + 8, y, w - 2 * pad - 16, 30, C.BorderMid);
            Gfx.Text(pad + 14, y + 7, saveNameBuf == null || saveNameBuf == "" ? "Untitled.txt" : saveNameBuf, C.OnLight);
            if ((Host.Ticks() / 30) % 2 == 0)
            {
                string shown = saveNameBuf == null || saveNameBuf == "" ? "Untitled.txt" : saveNameBuf;
                Gfx.FillRect(pad + 15 + Gfx.Measure(shown), y + 8, 2, 16, 0x1A1A1A);
            }
#if !WINHOST
            Host.SetImeAnchor(pad + 14, y + 7);
#endif
            y += 44;

            Gfx.Text(pad + 8, y, U.Cat("Detected content: ", DetectLabel()), C.TextFaint);
            y += 26;

            W.Button(pad + 8, y, 100, 30, "Save");
            W.Button(pad + 116, y, 100, 30, "Cancel");
            if (saveDirWarn != 0)
                Gfx.Text(pad + 230, y + 8, "last attempt failed (read-only or no such folder)", C.Danger);
        }

        void DrawPicker(int w, int h)
        {
            int pad = 10, y = 48;
            Gfx.Text(pad + 8, y, "Open from System (MKFS):", C.TextSub);
            y += 26;
            int n = Host.FileCount(0);
            for (int i = 0; i < n && i < 12; i++)
            {
                int ry = y + i * W.RowH;
                bool hot = W.Hot(pad, ry, w - 2 * pad, W.RowH - 2);
                if (hot) Gfx.FillRound(pad, ry, w - 2 * pad, W.RowH - 2, 6, C.Hover);
                Gfx.Icon(pad + 8, ry + 4, 22, 0x60A5FA, 'F', 0xFFFFFF);
                Gfx.Text(pad + 40, ry + 8, Host.FileName(1, i), C.Text);
            }
        }

        // 二进制（十六进制）视图：偏移 + 8 字节十六进制 + ASCII 栏。只读。
        void DrawBinary(int pad, int w, int h)
        {
            Gfx.FillRect(pad, 48, w - 2 * pad, h - 48 - pad, C.White);
            Gfx.FillRound(pad + 6, 52, w - 2 * pad - 12, 24, 4, 0xFFF3CD);
            Gfx.Text(pad + 12, 56, "二进制模式：该文件不是可解码文本，按原始字节显示", 0x7A4F00);
            int y = 84;
            int total = hex.Length / 2;
            for (int off = 0; off < total && y < h - pad - 12; off += 8)
            {
                string line = Hx8(off);
                line = U.Cat(line, "  ");
                for (int j = 0; j < 8; j++)
                {
                    if (off + j < total) line = U.Cat(line, HxSub(hex, (off + j) * 2, 2));
                    else line = U.Cat(line, "  ");
                    line = U.Cat(line, " ");
                }
                line = U.Cat(line, " ");
                for (int j = 0; j < 8; j++)
                {
                    if (off + j < total)
                    {
                        int v = HxByte(hex, (off + j) * 2);
                        if (v >= 0x20 && v < 0x7F) line = U.Cat(line, Host.CharStr(v));
                        else line = U.Cat(line, ".");
                    }
                }
                Gfx.Text(pad + 8, y, line, 0x1F2937);
                y += 18;
            }
        }
        static string HxSub(string s, int a, int len)
        {
            string r = "";
            for (int i = a; i < a + len && i < s.Length; i++) r = U.Cat(r, Host.CharStr((int)s[i]));
            return r;
        }
        static string Hx8(int v)
        {
            string r = "";
            for (int sh = 28; sh >= 0; sh -= 4)
            {
                int d = (v >> sh) & 15;
                r = U.Cat(r, Host.CharStr(d < 10 ? ('0' + d) : ('a' + d - 10)));
            }
            return r;
        }

        static void DrawLines(int x, int y, string s, uint col, int maxY, bool caret)
        {
            int n = s.Length, start = 0;
            for (int i = 0; i <= n; i++)
            {
                if (i == n || s[i] == '\n')
                {
                    // s[start..i) 已经是该行正确的 UTF-8 字节：直接把子串传给
                    // Gfx.Text 以渲染 CJK。旧的逐字节 Host.CharStr(s[j]) 循环
                    // 会重新编码每个 UTF-8 字节，draw_text_utf8 随后命中
                    // “2 字节 -> 跳过”分支 —— 中文消失。
                    string line = U.Sub(s, start, i - start);
                    if (i == n && caret && (Host.Ticks() / 30) % 2 == 0)
                        line = U.Cat(line, "|");
                    if (y < maxY) Gfx.Text(x, y, line, col);
                    y += 20; start = i + 1;
                }
            }
        }

        public override void OnClick(int mx, int my)
        {
            int w = Gfx.Width(), h = Gfx.Height();
            int pad = 10;

            // === 新增：点击正文区 -> 定位光标，开始拖选 ===
            if (!picking && !pickingSave && !binary)
            {
                int top = 54, left = pad + 8;
                int bodyY = 48, bodyH = h - 48 - pad;
                if (mx >= left && my >= top && my < top + bodyH)
                {
                    int pos = HitTestByte(mx, my, pad);
                    // Shift 点击扩展选区，普通点击重置锚点
                    if ((my & 0x10000) == 0) // 宿主的 shift 标记（示例占位）
                        selAnchorPos = pos;
                    t.cursor = pos;
                    UpdateSelectionFromMouse();
                    mouseSelecting = true;
                    return;
                }
            }

            if (U.In(mx, my, pad, 6, 70, 28)) { picking = !picking; pickingSave = false; return; }
            if (U.In(mx, my, pad + 80, 6, 70, 28))
            { t.text = ""; name = "Untitled"; picking = false; pickingSave = false; return; }
            if (U.In(mx, my, pad + 160, 6, 84, 28))
            {
                pickingSave = !pickingSave;
                picking = false;
                if (saveNameBuf == null || saveNameBuf == "")
                    saveNameBuf = (name == null || name == "Untitled") ? "Untitled.txt" : name;
                saveVol = (fs == 3) ? 1 : 0;
                return;
            }

            if (pickingSave)
            {
                int y0 = 84 + 22;
                for (int i = 0; i < 2; i++)
                {
                    int ry = y0 + i * W.RowH;
                    if (U.In(mx, my, pad, ry, w - 2 * pad, W.RowH - 2)) { saveVol = i; return; }
                }
                int yb = y0 + 2 * W.RowH + 10 + 22 + 22 + 44 + 26;
                if (U.In(mx, my, pad + 8, yb, 100, 30)) { SaveAs(); return; }
                if (U.In(mx, my, pad + 116, yb, 100, 30)) { pickingSave = false; return; }
            }

            if (picking)
            {
                int y = 48 + 26;
                int n = Host.FileCount(1);
                for (int i = 0; i < n && i < 12; i++)
                {
                    int ry = y + i * W.RowH;
                    if (U.In(mx, my, pad, ry, w - 2 * pad, W.RowH - 2))
                    {
                        LoadFile(1, Host.FileName(1, i));
                        picking = false;
                        return;
                    }
                }
            }
        }

        // === 新增：鼠标拖动扩展选区（宿主在拖动阶段回调） ===
        // 若宿主没有 OnDrag 回调，这段可忽略；但有了它就能实现“按住拖动选中”。
        public override void OnDrag(int phase, int mx, int my, int hitId, int hx, int hy)
        {
            if (!mouseSelecting) return;
            if (phase == 2)   // 释放
            {
                mouseSelecting = false;
                return;
            }
            if (phase == 1 && !binary && !picking && !pickingSave)   // 移动
            {
                int pad = 10;
                int pos = HitTestByte(mx, my, pad);
                if (pos != t.cursor)
                {
                    t.cursor = pos;
                    UpdateSelectionFromMouse();
                    Host.Repaint();
                }
            }
        }

        public override void OnKey(int ch)
        {
            if (pickingSave)
            {
                if (ch == -9) { pickingSave = false; return; }
                if (ch == -2 || ch == -3) { SaveAs(); return; }
                if (ch == -4)
                {
                    if (saveNameBuf != null && saveNameBuf.Length > 0)
                    {
                        int k = saveNameBuf.Length;
                        while (k > 0 && ((int)saveNameBuf[k - 1] & 0xC0) == 0x80) k--;
                        if (k > 0) k--;
                        saveNameBuf = k > 0 ? U.Sub(saveNameBuf, 0, k) : "";
                    }
                    return;
                }
                if (ch > 0) saveNameBuf = U.Cat(saveNameBuf == null ? "" : saveNameBuf, Host.CharStr(ch));
                return;
            }
            if (picking) { return; }
            if (binary) { return; }

            // === 新增：加载期间拒绝编辑（防止拼到半截文本里） ===
            if (loadActive) { return; }

            if (ch == -10) { Save(); return; }          // Ctrl+S -> 原地保存

            // === 新增：选区相关快捷键 ===
            // Ctrl+A 全选
            if (ch == -6)
            {
                t.selA = 0; t.selB = t.text.Length;
                t.cursor = t.text.Length;
                selAnchorPos = 0;
                return;
            }
            // 删除选区（Backspace/Delete）
            if ((ch == -4 || ch == -1 || ch == 8) && t.selB > t.selA)
            {
                DeleteSelection();
                saved = false;
                return;
            }
            // 打字替换选区
            if (ch > 0 && t.selB > t.selA)
            {
                DeleteSelection();
            }
            if (ch == -2) { t.Insert("\n"); saved = false; return; }
            t.Key(ch);
            saved = false;
        }

        // === 新增：删除当前选区 ===
        void DeleteSelection()
        {
            if (t.text == null || t.selB <= t.selA) return;
            int a = t.selA, b = t.selB;
            if (a < 0) a = 0;
            if (b > t.text.Length) b = t.text.Length;
            string left = a > 0 ? U.Sub(t.text, 0, a) : "";
            string right = b < t.text.Length ? U.Sub(t.text, b, t.text.Length - b) : "";
            t.text = U.Cat(left, right);
            t.cursor = a;
            t.selA = t.selB = a;
            selAnchorPos = a;
        }
    }
}
